// AC-0.7 The parity manifest is the removal gate for felix-erp-prototype (plan section 7).
// At S0 it must be complete and consistent; coverage grows slice by slice and S9 requires it full.
// The legacy navigation is a frozen copy (fixtures/legacy-navigation.json): the `groups` export of
// felix-erp-prototype/js/catalog.js at commit 0b4283e, generated by importing that module before the
// legacy directory was removed. Nothing in this test reads felix-erp-prototype/ any more.
// S9 (2026-11-05): a covered entry is evidenced either by executed tests or, for the prototype
// slices built under the no-new-tests decision, by the screens that deliver it plus a recorded
// smoke-check section in TEST_EVIDENCE.md. Nothing may stay planned. A dropped entry records its
// reason and the state of the user's approval.
import test from "node:test";
import assert from "node:assert/strict";
import { existsSync, readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const root = fileURLToPath(new URL("../../", import.meta.url));
const manifestPath = new URL("./parity-manifest.json", import.meta.url);
const load = () => {
  assert.ok(existsSync(manifestPath), "opex-prototype/tests/parity-manifest.json must exist");
  return JSON.parse(readFileSync(manifestPath, "utf8"));
};
const SLICES = ["S0", "S1", "S2", "S3", "S4", "S5", "S6", "S7", "S8", "S9"];
const LEVELS = ["D", "S", "N"];
const STATUSES = ["planned", "covered", "dropped"];
// "S" = present in the legacy prototype only as a simulation; the plan uses it for two rows.
const NOW = ["P", "~", "S", "A"];
const entries = (manifest) => [...manifest.routes, ...manifest.capabilities, ...manifest.baseline];
const sliceOf = (cell) => cell.split("/")[0].trim();

const { ROUTES } = await import("../ui/router.js");
const routePaths = new Set(ROUTES.map(({ path }) => path));
const evidenceText = readFileSync(new URL("../TEST_EVIDENCE.md", import.meta.url), "utf8");

const groups = JSON.parse(
  readFileSync(new URL("./fixtures/legacy-navigation.json", import.meta.url), "utf8")
);
const legacyRoutes = groups.flatMap(([group, items]) =>
  items.map(([label, route]) => ({ group, label, route }))
);

test("AC-0.7 the manifest exists and declares its source and schema", () => {
  const manifest = load();
  assert.equal(manifest.schemaVersion, 1);
  assert.equal(manifest.source.directory, "felix-erp-prototype");
  for (const key of ["routes", "capabilities", "baseline"])
    assert.ok(Array.isArray(manifest[key]) && manifest[key].length > 0, `${key} must be listed`);
});

test("AC-0.7 every legacy route is listed exactly once, with the legacy group and label", () => {
  const manifest = load();
  assert.equal(legacyRoutes.length, 42);
  assert.deepEqual(
    manifest.routes.map(({ route, group, label }) => ({ route, group, label })),
    legacyRoutes,
    "manifest routes must equal the legacy navigation, in order"
  );
});

test("AC-0.7 route kinds: 3 dashboards, 36 other tenant destinations, 3 platform destinations", () => {
  const manifest = load();
  const count = (kind) => manifest.routes.filter((entry) => entry.kind === kind).length;
  assert.equal(count("dashboard"), 3);
  assert.equal(count("tenant"), 36);
  assert.equal(count("platform"), 3);
  for (const entry of manifest.routes) {
    const expected =
      entry.group === "DASHBOARDS"
        ? "dashboard"
        : entry.group === "PLATFORM"
          ? "platform"
          : "tenant";
    assert.equal(entry.kind, expected, entry.route);
  }
});

test("AC-0.7 the README capabilities are listed, including the notification centre", () => {
  const manifest = load();
  const names = manifest.capabilities.map((entry) => entry.name.toLowerCase()).join("\n");
  for (const needle of [
    "notification centre",
    "three calculated dashboards",
    "tenant provisioning",
    "employee lifecycle",
    "attendance",
    "productionday entry",
    "rolling 90-day",
    "buyers",
    "capacity",
    "rfq",
    "inventory balances",
    "invoices",
    "role permission",
    "audit",
    "integration",
    "csv",
    "demo identities",
    "persistence",
  ])
    assert.ok(names.includes(needle), `capability for "${needle}" is missing`);
  assert.equal(
    new Set(manifest.capabilities.map((entry) => entry.id)).size,
    manifest.capabilities.length
  );
});

test("AC-0.7 every entry has a target slice, a demonstration level and a status", () => {
  const manifest = load();
  for (const entry of entries(manifest)) {
    const label = entry.route ?? entry.id;
    assert.ok(SLICES.includes(entry.slice), `${label}: slice ${entry.slice}`);
    assert.ok(LEVELS.includes(entry.level), `${label}: level ${entry.level}`);
    assert.ok(STATUSES.includes(entry.status), `${label}: status ${entry.status}`);
    assert.ok(Array.isArray(entry.tests), `${label}: tests must be a list`);
  }
});

test("AC-0.7 level N entries cite their source on the Limits page", () => {
  const manifest = load();
  const limits = entries(manifest).filter((entry) => entry.level === "N");
  assert.ok(limits.length > 0, "the N items from the plan must be recorded");
  for (const entry of limits)
    assert.ok(
      entry.limitsSource && entry.limitsSource.length > 3,
      `${entry.id ?? entry.route}: limitsSource`
    );
});

test("AC-0.7 S9 gate: a covered entry has tests or screens with recorded evidence; a dropped entry records its reason; none is planned", () => {
  const manifest = load();
  for (const entry of entries(manifest)) {
    const label = entry.route ?? entry.id;
    assert.notEqual(entry.status, "planned", `${label}: the S9 gate allows no planned entry`);
    if (entry.status === "dropped") {
      assert.ok(
        entry.reason && entry.reason.length > 20,
        `${label}: a dropped entry needs a reason`
      );
      assert.ok(entry.approval, `${label}: a dropped entry records the state of its approval`);
      continue;
    }
    for (const { file, name } of entry.tests) {
      const path = new URL(`../../${file}`, import.meta.url);
      assert.ok(existsSync(path), `${label}: ${file} must exist`);
      assert.ok(
        readFileSync(path, "utf8").includes(name),
        `${label}: "${name}" not found in ${file}`
      );
    }
    if (entry.tests.length > 0) continue;
    assert.ok(entry.screens?.length > 0, `${label}: covered without tests needs screens`);
    for (const screen of entry.screens)
      assert.ok(routePaths.has(screen), `${label}: screen ${screen} is not a route`);
    assert.ok(entry.evidence?.length > 0, `${label}: covered without tests needs evidence`);
    for (const heading of entry.evidence)
      assert.ok(
        evidenceText.includes(`## ${heading}`),
        `${label}: no TEST_EVIDENCE section "${heading}"`
      );
  }
});

const planRows = () => {
  const text = readFileSync(`${root}docs/engineering/plans/prototype-rebuild.md`, "utf8");
  const section = text.slice(text.indexOf("## Requirement baseline"), text.indexOf("\n## Slices"));
  return section
    .split("\n")
    .filter((line) => line.startsWith("|"))
    .map((line) =>
      line
        .split("|")
        .slice(1, -1)
        .map((cell) => cell.trim())
    )
    .filter((cells) => cells.length === 3 && !/^-+$/.test(cells[1]) && cells[1] !== "Now");
};

test("AC-0.7 the baseline matches the plan row for row, and no row is left unverified", () => {
  const manifest = load();
  const rows = planRows();
  assert.ok(rows.length >= 55, `expected the plan baseline tables, found ${rows.length} rows`);
  assert.deepEqual(
    manifest.baseline.map((entry) => entry.planRow),
    rows.map(([requirement]) => requirement),
    "manifest baseline must list every plan row in order"
  );
  rows.forEach(([requirement, now, slice], index) => {
    const entry = manifest.baseline[index];
    assert.ok(!now.includes("?"), `plan row still unverified: ${requirement}`);
    assert.ok(NOW.includes(entry.now), `${requirement}: now ${entry.now}`);
    assert.ok(now.startsWith(entry.now), `${requirement}: plan says ${now}, manifest ${entry.now}`);
    assert.equal(entry.slice, sliceOf(slice), `${requirement}: slice`);
  });
});

test("AC-0.7 the rows re-verified in S0 record what was found", () => {
  const manifest = load();
  const byId = Object.fromEntries(manifest.baseline.map((entry) => [entry.id, entry]));
  for (const id of [
    "FR-TEN-001",
    "FR-ORG-001..005",
    "FR-ORG-REORDER",
    "FR-ORG-006/007",
    "SRS-8.3",
    "FR-PROD-009",
    "FR-PROD-011",
    "SCREEN-EVENTS",
    "ARCH-CROSS-FACTORY",
    "SRS-7.4-ADJUSTMENT",
  ]) {
    assert.ok(byId[id], `${id} must be present`);
    assert.equal(byId[id].reverified, "2026-11-02", `${id}: reverified date`);
    assert.ok(byId[id].finding && byId[id].finding.length > 10, `${id}: finding`);
  }
});

test("AC-0.7 the slice S0 baseline rows are covered by executed tests", () => {
  const manifest = load();
  for (const entry of manifest.baseline.filter((row) => row.slice === "S0"))
    assert.equal(entry.status, "covered", `${entry.id}: S0 rows are delivered by this slice`);
});
